const EX43=[{"t": "Chờ n mili giây bằng ngắt", "d": "Đọc một chữ số n (1–9) bằng INT 21h hàm 08h. Code mẫu đã cài vectơ INT 60h, cho 8254 tạo ngắt mỗi 1 ms ở IR0 và khởi tạo 8259A (IR0 → INT 60h). Viết chương trình phục vụ ngắt isr (tăng tick, gửi EOI, IRET; cất và khôi phục thanh ghi nó dùng) và phần chính: cho phép ngắt, chờ tới khi tick = n, cấm ngắt rồi in n dấu *. Trang chấm chữ in ra, số ngắt CPU đã nhận (đúng n) và ISR của 8259A khi kết thúc (phải bằng 0).", "start": "; Bài tập 1: chờ n tick (1 ms) bằng ngắt rồi in n dấu *\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntick    DB      0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một chữ số n (1-9)\n        INT     21H\n        SUB     AL, '0'\n        MOV     BL, AL                  ; BL = n\n        CLI\n        PUSH    DS                      ; cài vectơ 60h qua INT 21h/25h\n        MOV     AX, CS\n        MOV     DS, AX\n        MOV     DX, OFFSET isr\n        MOV     AX, 2560H\n        INT     21H\n        POP     DS\n        MOV     AL, 34H                 ; 8254 bộ đếm 0, mode 2\n        OUT     8EH, AL\n        MOV     AX, 2500                ; 1 ms\n        OUT     88H, AL\n        MOV     AL, AH\n        OUT     88H, AL\n        MOV     AL, 13H                 ; ICW1: cạnh, một chip, có ICW4\n        OUT     90H, AL\n        MOV     AL, 60H                 ; ICW2: IR0 → INT 60h\n        OUT     92H, AL\n        MOV     AL, 01H                 ; ICW4: 8086, EOI thường\n        OUT     92H, AL\n        MOV     AL, 0FEH                ; OCW1: IMR\n        OUT     92H, AL\n; TODO: STI, chờ tick = n, CLI, in n dấu *\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nisr     PROC\n; TODO: tăng tick, gửi EOI\n        IRET\nisr     ENDP\n        END     MAIN\n", "tests": [{"in": "3", "out": "***", "io": {"want": {"ints": 3, "isr": 0}}}, {"in": "1", "out": "*", "io": {"want": {"ints": 1, "isr": 0}}}, {"in": "9", "out": "*********", "io": {"want": {"ints": 9, "isr": 0}}}, {"in": "5", "out": "*****", "io": {"want": {"ints": 5, "isr": 0}}}, {"in": "2", "out": "**", "io": {"want": {"ints": 2, "isr": 0}}}, {"in": "7", "out": "*******", "io": {"want": {"ints": 7, "isr": 0}}}]}, {"t": "Đếm nút nhấn trong 20 ms", "d": "Code mẫu cho tick tăng mỗi 1 ms (IR0 → INT 60h) và in biến nhan sau 20 tick. Nút ngắt của bo nối IR1. Thêm: vectơ INT 61h trỏ tới một chương trình phục vụ mới tăng biến nhan (và gửi EOI), và mở IR1 trong IMR. Chương trình in số lần nhấn (0–9) trong 20 ms đầu và giữ biến nhan đúng giá trị đó. Mỗi test nhấn nút ở các thời điểm khác nhau (có test nhấn sau khi chương trình đã kết thúc: không được tính).", "start": "; Bài tập 2: đếm số lần nhấn nút ngắt (IR1) trong 20 ms\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntick    DB      0                       ; số tick 1 ms\nnhan    DB      0                       ; số lần nhấn nút\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        CLI\n        PUSH    DS                      ; cài vectơ 60h qua INT 21h/25h\n        MOV     AX, CS\n        MOV     DS, AX\n        MOV     DX, OFFSET isr\n        MOV     AX, 2560H\n        INT     21H\n        POP     DS\n        MOV     AL, 34H                 ; 8254 bộ đếm 0, mode 2\n        OUT     8EH, AL\n        MOV     AX, 2500                ; 1 ms\n        OUT     88H, AL\n        MOV     AL, AH\n        OUT     88H, AL\n        MOV     AL, 13H                 ; ICW1: cạnh, một chip, có ICW4\n        OUT     90H, AL\n        MOV     AL, 60H                 ; ICW2: IR0 → INT 60h\n        OUT     92H, AL\n        MOV     AL, 01H                 ; ICW4: 8086, EOI thường\n        OUT     92H, AL\n        MOV     AL, 0FEH                ; OCW1: IMR\n        OUT     92H, AL\n        STI\ncho:\n        CMP     tick, 20\n        JB      cho\n        CLI\n        MOV     DL, nhan\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nisr     PROC\n        PUSH    AX\n        PUSH    DS\n        MOV     AX, @DATA               ; ngắt đến bất kỳ lúc nào: tự nạp DS\n        MOV     DS, AX\n        INC     tick\n        MOV     AL, 20H                 ; OCW2: EOI không chỉ định\n        OUT     90H, AL\n        POP     DS\n        POP     AX\n        IRET\nisr     ENDP\n        END     MAIN\n", "tests": [{"out": "0", "io": {"irq1": [], "want": {"isr": 0}}, "mem": [{"at": "nhan", "bytes": [0]}]}, {"out": "1", "io": {"irq1": [5000], "want": {"isr": 0}}, "mem": [{"at": "nhan", "bytes": [1]}]}, {"out": "2", "io": {"irq1": [5000, 30000], "want": {"isr": 0}}, "mem": [{"at": "nhan", "bytes": [2]}]}, {"out": "4", "io": {"irq1": [3000, 15000, 40000, 60000], "want": {"isr": 0}}, "mem": [{"at": "nhan", "bytes": [4]}]}, {"out": "1", "io": {"irq1": [3000, 150000], "want": {"isr": 0}}, "mem": [{"at": "nhan", "bytes": [1]}]}, {"out": "5", "io": {"irq1": [4000, 10000, 20000, 30000, 50000], "want": {"isr": 0}}, "mem": [{"at": "nhan", "bytes": [5]}]}]}, {"t": "CPU còn rảnh bao nhiêu khi có ngắt 10 kHz", "d": "8254 tạo ngắt mỗi 100 µs (500 chu kỳ CPU). Phần chính lặp “một đơn vị việc” và đếm số vòng vào biến viec (word) cho tới khi tick = T (T đọc từ công tắc). Code mẫu đúng nhưng chương trình phục vụ ngắt cất cả 8 thanh ghi, còn vòng chính tăng biến trên bộ nhớ, nên CPU làm được ít việc. Viết lại (chương trình phục vụ ngắt và vòng chính) để viec đạt mức tối thiểu của từng test. Vẫn đếm đúng tick, gửi EOI (hoặc dùng AEOI), không đổi tần số ngắt.", "start": "; Bài tập 3: CPU còn rảnh bao nhiêu khi có ngắt 10 kHz?\n; Bản này đúng nhưng ISR và vòng việc chính chậm.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntick    DB      0\nviec    DW      0                       ; số vòng việc chính đã làm\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 8BH                 ; 8255A: B, C vào\n        OUT     86H, AL\n        IN      AL, 82H                 ; T = số tick cần chạy\n        MOV     BL, AL\n        CLI\n        PUSH    DS                      ; cài vectơ 60h qua INT 21h/25h\n        MOV     AX, CS\n        MOV     DS, AX\n        MOV     DX, OFFSET isr\n        MOV     AX, 2560H\n        INT     21H\n        POP     DS\n        MOV     AL, 34H                 ; bộ đếm 0, mode 2\n        OUT     8EH, AL\n        MOV     AX, 250                 ; 100 µs = 500 chu kỳ CPU\n        OUT     88H, AL\n        MOV     AL, AH\n        OUT     88H, AL\n        MOV     AL, 13H                 ; ICW1: cạnh, một chip, có ICW4\n        OUT     90H, AL\n        MOV     AL, 60H                 ; ICW2: IR0 → INT 60h\n        OUT     92H, AL\n        MOV     AL, 01H                 ; ICW4\n        OUT     92H, AL\n        MOV     AL, 0FEH                ; OCW1: IMR\n        OUT     92H, AL\n        STI\nlam:\n        INC     viec                    ; một đơn vị việc\n        CMP     tick, BL\n        JB      lam\n        CLI\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nisr     PROC                            ; cất mọi thanh ghi \"cho chắc\"\n        PUSH    AX\n        PUSH    BX\n        PUSH    CX\n        PUSH    DX\n        PUSH    SI\n        PUSH    DI\n        PUSH    DS\n        PUSH    ES\n        MOV     AX, @DATA\n        MOV     DS, AX\n        INC     tick\n        MOV     DX, 0090H\n        MOV     AL, 20H\n        OUT     DX, AL\n        POP     ES\n        POP     DS\n        POP     DI\n        POP     SI\n        POP     DX\n        POP     CX\n        POP     BX\n        POP     AX\n        IRET\nisr     ENDP\n        END     MAIN\n", "tests": [{"io": {"sw": 10, "want": {"ints": 10, "isr": 0, "min": {"viec": 90}}}}, {"io": {"sw": 20, "want": {"ints": 20, "isr": 0, "min": {"viec": 180}}}}, {"io": {"sw": 30, "want": {"ints": 30, "isr": 0, "min": {"viec": 270}}}}, {"io": {"sw": 40, "want": {"ints": 40, "isr": 0, "min": {"viec": 360}}}}, {"io": {"sw": 50, "want": {"ints": 50, "isr": 0, "min": {"viec": 450}}}}, {"io": {"sw": 25, "want": {"ints": 25, "isr": 0, "min": {"viec": 225}}}}]}];
const ex43=makeX86Ex(document.getElementById("ex-l43"),sim43,EX43);
makeX86IO(sim43,{show:["pit", "pic"],presets:[{}, {}, {}, {}, {}, {"irq1": [1000]}, {}],ex:document.getElementById("ex-l43"),exList:EX43,exCur:()=>ex43.cur});

makeQuiz("quiz43","score43",[{"q": "8259A khởi tạo với ICW2 = 60h. Thiết bị ở IR3 yêu cầu ngắt và được CPU nhận. CPU đọc vectơ ở địa chỉ vật lý nào?", "o": ["00180h (vectơ 60h × 4)", "0018Ch (vectơ 63h × 4)", "0000Ch (vectơ 03h × 4)", "00063h (vectơ 63h, không nhân 4)"], "a": 1, "e": "Số hiệu = ICW2 (5 bit cao) + số IR = 60h + 3 = 63h. Mỗi vectơ 4 byte nên địa chỉ là 63h × 4 = 18Ch."}, {"q": "Chương trình phục vụ IR0 không gửi EOI. Điều gì xảy ra với các ngắt IR0 sau đó (fully nested, ưu tiên cố định)?", "o": ["Vẫn được nhận bình thường vì IRET đã bật lại IF", "Không được nhận nữa: bit 0 của ISR vẫn lập", "Được nhận nhưng nhảy tới vectơ của IR7", "8259A tự gửi EOI sau 1 ms"], "a": 1, "e": "Không có EOI, ISR bit 0 giữ 1; 8259A chỉ gửi yêu cầu có ưu tiên cao hơn mọi bit đang lập trong ISR, nên IR0 (và IR1–IR7) bị chặn (Ví dụ 3)."}, {"q": "Trong hệ 8086 dùng một 8259A, ICW1 nào đúng nếu cần kích theo cạnh và có ICW4?", "o": ["12h", "1Bh", "13h", "11h"], "a": 2, "e": "13h = 0001 0011b: D4 = 1 (ICW1), LTIM = 0 (cạnh), SNGL = 1 (một chip), IC4 = 1. 12h thiếu IC4 (Ví dụ 4); 1Bh là kích theo mức; 11h là ghép tầng (cần ICW3)."}, {"q": "Đoạn <code>CLI<\/code> · <code>INT 60h<\/code> chạy khi IMR = FFh. Chương trình phục vụ của vectơ 60h có chạy không?", "o": ["Có: INT n là ngắt mềm, không qua 8259A và không bị IF chặn", "Không: IF = 0 chặn mọi ngắt", "Không: IMR = FFh che vectơ 60h", "Chỉ chạy nếu ICW2 = 60h"], "a": 0, "e": "CLI và IMR chỉ ảnh hưởng ngắt phần cứng qua INTR. INT 60h là một lệnh, luôn chạy (Ví dụ 7)."}, {"q": "Ngắt 10 kHz trên CPU 5 MHz, mỗi lần ngắt tốn 163 chu kỳ (kể cả nhận ngắt và IRET). Chương trình chính còn khoảng bao nhiêu phần trăm thời gian CPU?", "o": ["Khoảng 67 %", "Khoảng 97 %", "Khoảng 33 %", "100 %, vì ngắt chạy song song với chương trình chính"], "a": 0, "e": "10 kHz ở 5 MHz là 500 chu kỳ mỗi lần ngắt; 163 / 500 ≈ 33 % cho ngắt, còn khoảng 67 % cho chương trình chính. CPU chỉ có một luồng lệnh: ngắt lấy thời gian của chương trình chính."}]);

